import unittest

from billing.pagination import page_count, invoice_total


class BillingTest(unittest.TestCase):
    def test_page_count(self):
        self.assertEqual(page_count(10, 5), 2)
        self.assertEqual(page_count(11, 5), 3)

    def test_total(self):
        self.assertEqual(invoice_total([{"quantity": 2, "unit_cents": 150}]), 300)


if __name__ == "__main__":
    unittest.main()

